const topics = [
  { slug:"fat-dissolving-injections-side-effects-safety", category:"body-contouring", specialties:["body-contouring"], author:"shimaa-fouad", image:"assets/img/articles/fat-injections-safety-cover.webp", title:L("إبر إذابة الدهون: المكونات والآثار الجانبية وأسئلة الأمان","Fat-dissolving injections: ingredients, side effects and safety questions"), excerpt:L("فهم المادة المستخدمة، المكان المقترح والبدائل أهم من مطاردة نتيجة سريعة أو اسم منتج متداول.","Knowing the substance, proposed area and alternatives matters more than chasing a quick result or a product name."), key:L("إبر إذابة الدهون وأضرارها","fat dissolving injections side effects"), focus:L("إبر إذابة الدهون إجراءات موضعية تحتاج شرحاً دقيقاً للمادة والمنطقة والهدف قبل التفكير فيها","Fat-dissolving injections are local procedures that need a precise explanation of the substance, area and goal before they are considered"), pattern:L("السؤال المفيد ليس هل الإبر تعمل للجميع، بل ما المشكلة التي نريد تقييمها وهل هي دهون موضعية فعلاً أم شيء آخر","The useful question is not whether injections work for everyone, but what concern is being assessed and whether it is truly local fat or something else"), factors:L("نوع المادة، مصدرها، خبرة الممارس، موضع الحقن، الجلد المحيط، التاريخ المرضي والأدوية الحالية كلها تغير قرار الأمان","The substance, its source, the clinician’s training, injection site, surrounding skin, health history and current medicines all change the safety decision"), urgent:L("ألم شديد متزايد، تغير واضح في لون الجلد، تورم سريع، ضيق نفس أو أعراض عامة بعد إجراء يستلزم تقييماً عاجلاً","Rapid swelling, severe worsening pain, a marked skin-colour change, breathing difficulty or systemic symptoms after a procedure need urgent assessment"), source:["FDA, Deoxycholic acid injection", "https://www.fda.gov/drugs/drug-safety-and-availability/fda-approves-k-ybella-treat-double-chin"] },
  { slug:"inbody-test-first-visit-guide", category:"body-contouring", specialties:["clinical-nutrition","body-contouring"], author:"shimaa-fouad", image:"assets/img/articles/inbody-first-visit-cover.webp", title:L("تحليل InBody لأول مرة: ماذا يقيس وكيف تستعد له؟","Your first InBody test: what it measures and how to prepare"), excerpt:L("القياس أداة متابعة، لا حكم على الجسم ولا تشخيص بمفرده. الاستعداد المتسق يساعد في مقارنة عادلة.","A measurement is a follow-up tool, not a judgement of a body or a diagnosis by itself. Consistent preparation supports fair comparison."), key:L("ما هو تحليل InBody والتحضير له","what is an InBody test and how to prepare"), focus:L("تحليل تركيب الجسم يقدّر مكونات الجسم في وقت محدد، وتظهر فائدته الأكبر عند قراءته مع الهدف والمتابعة","A body-composition test estimates body components at one point in time and is most useful when read with goals and follow-up"), pattern:L("رقم واحد لا يشرح الصحة أو سبب تغير الوزن؛ الاتجاه عبر قياسات متقاربة الظروف هو الأكثر قابلية للنقاش","One number does not explain health or a reason for weight change; trends measured under comparable conditions are more useful to discuss"), factors:L("الأكل والشرب والتمرين والوقت من اليوم وتغير السوائل والدورة الشهرية عند وجودها قد تؤثر في المقارنة","Food, fluids, exercise, time of day, fluid shifts and menstrual-cycle timing where relevant can affect comparisons"), urgent:L("القياس ليس مناسباً لتقييم أعراض حادة مثل ألم الصدر أو الدوار الشديد أو ضيق النفس؛ هذه تحتاج رعاية طبية مستقلة","A scan is not a tool for urgent symptoms such as chest pain, severe dizziness or breathlessness; those need independent medical care"), source:["Cleveland Clinic, Body Composition", "https://my.clevelandclinic.org/health/diagnostics/22523-body-composition"] },
  { slug:"ibs-symptoms-women-assessment-guide", category:"gastroenterology-hepatology", specialties:["gastroenterology-hepatology","internal-medicine"], author:"mohab-ashraf", image:"assets/img/articles/ibs-women-cover.webp", title:L("أعراض القولون العصبي عند النساء: كيف نحضر لتقييم منظم؟","IBS symptoms in women: how to prepare for an organised assessment"), excerpt:L("الألم والانتفاخ وتغير التبرز لها أسباب متعددة. النمط والسياق والعلامات المصاحبة أهم من التشخيص الذاتي.","Pain, bloating and bowel changes have several possible causes. Pattern, context and accompanying signs matter more than self-diagnosis."), key:L("أعراض القولون العصبي عند النساء","IBS symptoms in women"), focus:L("أعراض تشبه القولون العصبي تحتاج قراءة منظمة للتوقيت والنمط وعلاقتها بالتبرز والأكل والدورة والأدوية","IBS-like symptoms need an organised reading of timing, pattern and their relationship to bowel movements, food, cycle and medicines"), pattern:L("تسجيل الألم والانتفاخ وطبيعة التبرز ومدته يساعد على وصف ما يحدث، لكنه لا يثبت سبباً بعينه","Recording pain, bloating, stool pattern and duration helps describe what is happening, but does not prove one cause"), factors:L("الحمل أو احتمال الحمل، تغيرات الدورة، أدوية جديدة، جراحة سابقة، تاريخ عائلي وأي نزف أو فقدان وزن كلها تفاصيل مهمة","Pregnancy or possible pregnancy, cycle changes, new medicines, earlier surgery, family history, bleeding or weight loss are all important details"), urgent:L("نزف، براز أسود، قيء متكرر، ألم شديد متصاعد، إغماء، حرارة مستمرة أو فقدان وزن غير مقصود يحتاج تقييماً أسرع","Bleeding, black stool, repeated vomiting, escalating severe pain, fainting, persistent fever or unintentional weight loss need faster assessment"), source:["NIDDK, Irritable Bowel Syndrome", "https://www.niddk.nih.gov/health-information/digestive-diseases/irritable-bowel-syndrome"] },
  { slug:"ibs-symptoms-men-assessment-guide", category:"gastroenterology-hepatology", specialties:["gastroenterology-hepatology","internal-medicine"], author:"mohab-ashraf", image:"assets/img/articles/ibs-men-cover.webp", title:L("أعراض القولون العصبي عند الرجال: متى نتابع النمط ومتى نطلب فحصاً؟","IBS symptoms in men: when to track a pattern and when to seek assessment"), excerpt:L("التغيير في الإخراج أو ألم البطن لا يساوي تلقائياً قولوناً عصبياً. القصة الكاملة توجه الخطوة التالية.","A bowel change or abdominal pain does not automatically mean IBS. The complete story guides the next step."), key:L("أعراض القولون العصبي عند الرجال","IBS symptoms in men"), focus:L("أعراض القولون العصبي المشتبه بها عند الرجال تستحق وصفاً دقيقاً قبل تثبيت أي تسمية","Suspected IBS symptoms in men deserve a precise description before any label is settled"), pattern:L("ارتباط الألم بالتبرز وتغير التكرار أو القوام، مع مدة الأعراض وتأثيرها اليومي، تفاصيل تساعد الطبيب","The relation of pain to bowel movements, frequency or stool-form changes, duration and daily impact are details that help a clinician"), factors:L("العمر، التدخين، الأدوية، المكملات، السفر، عدوى حديثة والتاريخ العائلي لأمراض الأمعاء قد تغير التقييم","Age, smoking, medicines, supplements, travel, recent infection and family history of bowel disease can change assessment"), urgent:L("نزف أو براز أسود، ألم شديد، قيء متكرر، حمى، كتلة ملحوظة أو تدهور سريع لا ينبغي تفسيره كقولون من دون فحص","Bleeding or black stool, severe pain, repeated vomiting, fever, a noticeable mass or rapid deterioration should not be explained as IBS without examination"), source:["NIDDK, Irritable Bowel Syndrome", "https://www.niddk.nih.gov/health-information/digestive-diseases/irritable-bowel-syndrome"] },
  { slug:"severe-ibs-symptoms-red-flags", category:"gastroenterology-hepatology", specialties:["gastroenterology-hepatology","internal-medicine"], author:"mohab-ashraf", image:"assets/img/articles/severe-ibs-cover.webp", title:L("أعراض قولون شديدة: ما العلامات التي لا ينبغي تأجيل تقييمها؟","Severe IBS-like symptoms: which signs should not wait for assessment?"), excerpt:L("القولون العصبي قد يسبب إزعاجاً حقيقياً، لكن علامات معينة تحتاج تقييماً أوسع بدلاً من افتراض التشخيص.","IBS can cause real distress, but certain signs need broader assessment rather than an assumed diagnosis."), key:L("أعراض القولون العصبي الشديد","severe IBS symptoms"), focus:L("شدة الأعراض لا تؤكد وحدها القولون العصبي؛ التغير الجديد أو المتصاعد يحتاج ترتيب الأولويات بأمان","Severity alone does not confirm IBS; new or escalating symptoms need safe prioritisation"), pattern:L("مدة الألم، هل يوقظ من النوم، تأثيره على الشرب والأكل، ووجود تغيرات في البراز أهم من وصف عام مثل شديد","Duration, waking from sleep, effect on eating or drinking and bowel changes are more useful than a broad description such as severe"), factors:L("السن، الأمراض المزمنة، الأدوية، سفر حديث، استخدام مضادات حيوية أو وجود تاريخ عائلي كلها قد توجه الفحوص","Age, chronic conditions, medicines, recent travel, antibiotic use and family history may guide testing"), urgent:L("ألم شديد مفاجئ، انتفاخ مع قيء، دم، جفاف، إغماء أو صعوبة في التنفس يستلزم رعاية عاجلة وليس متابعة منزلية","Sudden severe pain, swelling with vomiting, blood, dehydration, fainting or breathing difficulty need urgent care rather than home monitoring"), source:["NHS, Irritable bowel syndrome", "https://www.nhs.uk/conditions/irritable-bowel-syndrome-ibs/"] },
  { slug:"fatty-liver-treatment-and-follow-up", category:"gastroenterology-hepatology", specialties:["gastroenterology-hepatology","clinical-nutrition"], author:"mohab-ashraf", image:"assets/img/articles/fatty-liver-treatment-cover.webp", title:L("الكبد الدهني: ما الذي يدخل في خطة علاج ومتابعة واقعية؟","Fatty liver: what belongs in a realistic treatment and follow-up plan?"), excerpt:L("لا يوجد حل منزلي سريع للكبد الدهني. تقييم السبب ودرجة الخطورة وخطة قابلة للاستمرار أهم من وعود الأسبوعين.","There is no quick home cure for fatty liver. Cause, risk assessment and a sustainable plan matter more than two-week promises."), key:L("علاج الكبد الدهني","fatty liver treatment"), focus:L("الكبد الدهني يحتاج فهم السبب وعوامل الخطورة والمتابعة المناسبة، لا وصفة موحدة أو مكملات عشوائية","Fatty liver needs an understanding of cause, risk factors and suitable follow-up, not one universal recipe or random supplements"), pattern:L("قد لا يسبب الكبد الدهني أعراضاً واضحة، لذلك الاعتماد على الإحساس وحده لا يحدد النشاط أو التحسن","Fatty liver may cause no clear symptoms, so feelings alone do not establish severity or improvement"), factors:L("السكر والدهون والوزن والأدوية والكحول والحالات الصحية ونتائج التحاليل والتصوير كلها تقرأ معاً","Glucose, blood fats, weight, medicines, alcohol, health conditions and test or imaging results are read together"), urgent:L("اصفرار جديد، قيء مستمر، ألم شديد، ارتباك، انتفاخ سريع في البطن أو نزف يحتاج تقييماً عاجلاً","New jaundice, persistent vomiting, severe pain, confusion, rapid abdominal swelling or bleeding need urgent assessment"), source:["NIDDK, NAFLD & NASH", "https://www.niddk.nih.gov/health-information/liver-disease/nafld-nash"] },
  { slug:"h-pylori-symptoms-and-testing-pathway", category:"gastroenterology-hepatology", specialties:["gastroenterology-hepatology","internal-medicine"], author:"mohab-ashraf", image:"assets/img/articles/h-pylori-testing-cover.webp", title:L("جرثومة المعدة: الأعراض وحدها لا تكفي: كيف نفكر في التحليل؟","H. pylori: symptoms alone are not enough: how testing is considered"), excerpt:L("الحرقان والانتفاخ وألم أعلى البطن ليست تشخيصاً بحد ذاتها. الاختبار المناسب والتوقيت يحددهما السياق.","Heartburn, bloating and upper-abdominal pain are not diagnoses by themselves. Context guides the right test and timing."), key:L("جرثومة المعدة أعراض وتحاليل","H. pylori symptoms and testing"), focus:L("التفكير في جرثومة المعدة يبدأ من القصة والعلامات وليس من اختبار عشوائي أو علاج من دون تشخيص","Thinking about H. pylori starts with history and signs, not a random test or treatment without diagnosis"), pattern:L("موضع الألم، ارتباطه بالأكل، الغثيان، استخدام مسكنات أو أدوية حموضة ومدة الأعراض معلومات مفيدة","Pain location, relation to meals, nausea, painkiller or acid-medicine use and symptom duration are useful information"), factors:L("العمر، فقدان الوزن، النزف، القيء، فقر الدم، جراحة سابقة والأدوية قد تغير قرار التحليل أو المنظار","Age, weight loss, bleeding, vomiting, anaemia, earlier surgery and medicines can change a testing or endoscopy decision"), urgent:L("قيء دموي أو يشبه القهوة، براز أسود، ألم شديد، إغماء أو صعوبة في شرب السوائل يحتاج تقييماً عاجلاً","Vomiting blood or coffee-ground material, black stool, severe pain, fainting or inability to drink needs urgent assessment"), source:["NIDDK, H. pylori and peptic ulcers", "https://www.niddk.nih.gov/health-information/digestive-diseases/peptic-ulcers-stomach-ulcers"] },
  { slug:"h-pylori-children-when-testing-considered", category:"pediatrics", specialties:["pediatrics","gastroenterology-hepatology"], author:"alyaa-abu-taleb", image:"assets/img/articles/h-pylori-children-testing-cover.webp", title:L("جرثومة المعدة عند الأطفال: متى يفكر الطبيب في التحليل؟","H. pylori in children: when might a clinician consider testing?"), excerpt:L("ألم البطن المتكرر لا يعني تلقائياً جرثومة معدة. عمر الطفل والنمو والعلامات المصاحبة توجه التقييم.","Recurrent tummy pain does not automatically mean H. pylori. Age, growth and accompanying signs guide assessment."), key:L("جرثومة المعدة عند الأطفال","H. pylori symptoms in children"), focus:L("تحليل جرثومة المعدة للطفل قرار سريري يرتبط بالقصة والنمو والفحص وليس عرضاً منفرداً","H. pylori testing in a child is a clinical decision linked to history, growth and examination, not one isolated symptom"), pattern:L("وقت الألم، أثره على الأكل والنوم والمدرسة، القيء أو تغير التبرز وقياسات النمو تساعد في الصورة","Timing of pain, effect on food, sleep and school, vomiting or bowel changes and growth measurements help build the picture"), factors:L("العمر، الأدوية، التاريخ العائلي، استخدام مسكنات وأي نزف أو فقدان وزن عوامل تهم الطبيب","Age, medicines, family history, painkiller use and any bleeding or weight loss matter to a clinician"), urgent:L("خمول واضح، قيء أخضر أو دموي، براز أسود أو دموي، ألم شديد أو عدم القدرة على الشرب يحتاج رعاية عاجلة","Marked lethargy, green or bloody vomit, black or bloody stool, severe pain or inability to drink need urgent care"), source:["ESPGHAN/NASPGHAN guideline", "https://pubmed.ncbi.nlm.nih.gov/28541262/"] },
  { slug:"insulin-resistance-adults-symptoms-testing", category:"internal-medicine", specialties:["internal-medicine","clinical-nutrition"], author:"mohab-ashraf", image:"assets/img/articles/insulin-resistance-adults-cover.webp", title:L("مقاومة الإنسولين: الأعراض والتحاليل وخطوات التقييم المنظم","Insulin resistance: symptoms, tests and an organised assessment"), excerpt:L("التعب أو زيادة الوزن لا يثبتان مقاومة الإنسولين. التشخيص يعتمد على التاريخ والفحص والتحاليل المناسبة عند طلبها.","Tiredness or weight gain does not prove insulin resistance. Diagnosis relies on history, examination and suitable tests when indicated."), key:L("أعراض مقاومة الإنسولين وعلاجها","insulin resistance symptoms and testing"), focus:L("مقاومة الإنسولين ليست نتيجة يمكن تأكيدها من عرض واحد أو رقم منفصل عن السياق","Insulin resistance is not a result confirmed from one symptom or one number outside context"), pattern:L("تغير الوزن أو الشهية أو الطاقة قد يكون له أكثر من تفسير، لذلك يفيد وصف الزمن والأدوية والنوم والنشاط","Changes in weight, appetite or energy can have more than one explanation, so timing, medicines, sleep and activity are useful to describe"), factors:L("ضغط الدم، الدهون، السكر، التاريخ العائلي، الحمل السابق، الأدوية والحالات الهرمونية قد تكون مهمة في التقييم","Blood pressure, lipids, glucose, family history, earlier pregnancy, medicines and hormonal conditions may matter in assessment"), urgent:L("عطش شديد جديد مع تبوّل متكرر، قيء، ارتباك، ضعف شديد أو ألم صدر يحتاج تقييماً عاجلاً","New intense thirst with frequent urination, vomiting, confusion, severe weakness or chest pain needs urgent assessment"), source:["NIDDK, Insulin Resistance & Prediabetes", "https://www.niddk.nih.gov/health-information/diabetes/overview/what-is-diabetes/prediabetes-insulin-resistance"] },
  { slug:"insulin-resistance-children-family-assessment", category:"pediatrics", specialties:["pediatrics","clinical-nutrition"], author:"alyaa-abu-taleb", image:"assets/img/articles/insulin-resistance-children-cover.webp", title:L("مقاومة الإنسولين عند الأطفال: كيف يكون التقييم وخطة الأسرة؟","Insulin resistance in children: assessment and a family-centred plan"), excerpt:L("لا ينبغي تحويل شكل الجسم أو عرض واحد إلى تشخيص. النمو والتاريخ العائلي والفحص يحددون إن كانت التحاليل مناسبة.","A body shape or one symptom should not become a diagnosis. Growth, family history and examination guide whether tests are appropriate."), key:L("مقاومة الإنسولين للأطفال","insulin resistance in children"), focus:L("تقييم الطفل يركز على نموه وصحته وسياقه العائلي بدلاً من لوم الطفل أو مطاردة رقم واحد","A child’s assessment focuses on growth, health and family context rather than blame or chasing one number"), pattern:L("التغيرات في الشهية أو الوزن أو الجلد أو النشاط تسجل مع النمو والأدوية والعادات اليومية، لا كدليل منفرد","Changes in appetite, weight, skin or activity are recorded with growth, medicines and daily habits, not as standalone proof"), factors:L("البلوغ، التاريخ العائلي، النوم، أدوية معينة، ضغط الدم ونتائج سابقة قد تؤثر في قرار التقييم","Puberty, family history, sleep, certain medicines, blood pressure and earlier results can affect an assessment decision"), urgent:L("قيء متكرر، تنفس سريع، خمول شديد، ارتباك أو عدم القدرة على الشرب يستدعي رعاية عاجلة","Repeated vomiting, fast breathing, marked lethargy, confusion or inability to drink requires urgent care"), source:["NIDDK, Insulin Resistance & Prediabetes", "https://www.niddk.nih.gov/health-information/diabetes/overview/what-is-diabetes/prediabetes-insulin-resistance"] },
  { slug:"dark-neck-skin-children-assessment", category:"pediatrics", specialties:["pediatrics","dermatology"], author:"alyaa-abu-taleb", image:"assets/img/articles/dark-neck-children-cover.webp", title:L("اسمرار الرقبة عند الأطفال: متى نراجع الجلد ومتى نطلب تقييماً؟","Dark neck skin in children: when to review the skin and seek assessment"), excerpt:L("تغير اللون قد يرتبط بالاحتكاك أو تهيج أو أسباب أخرى. الفحص يساعد في التفريق بدل استخدام خلطات تفتيح.","Colour change can relate to friction, irritation or other causes. Examination helps distinguish them instead of using lightening mixtures."), key:L("اسمرار الرقبة عند الأطفال","dark neck skin in children"), focus:L("اسمرار الرقبة عند الطفل وصف جلدي يحتاج سياقاً، وليس تشخيصاً أو سبباً مؤكداً من الصورة فقط","Dark neck skin in a child is a skin description needing context, not a diagnosis or proven cause from a photo alone"), pattern:L("مكان التغير وملمسه ووقت ظهوره وما استُخدم على الجلد وأي تغير في النمو أو الصحة تفاصيل تفيد التقييم","Location, texture, onset, products used and any change in growth or health are useful assessment details"), factors:L("الاحتكاك، العطور والمنتجات، تاريخ الإكزيما، الأدوية، البلوغ والعوامل العائلية قد تدخل في الصورة","Friction, fragrance and products, eczema history, medicines, puberty and family factors may all be part of the picture"), urgent:L("تورم سريع، طفح مؤلم منتشر، صعوبة تنفس، حمى مع تدهور عام أو تغير سريع جداً يحتاج تقييماً عاجلاً","Rapid swelling, a painful widespread rash, breathing difficulty, fever with deterioration or a very rapid change needs urgent assessment"), source:["American Academy of Dermatology, Acanthosis nigricans", "https://www.aad.org/public/diseases/a-z/acanthosis-nigricans-overview"] },
  { slug:"acne-oily-skin-gentle-routine", category:"dermatology", specialties:["dermatology"], author:"shimaa-fouad", image:"assets/img/articles/acne-oily-skin-cover.webp", title:L("حب الشباب والبشرة الدهنية: روتين هادئ وأسئلة مهمة للطبيب","Acne and oily skin: a gentle routine and useful questions for dermatology"), excerpt:L("اللمعان لا يعني أن البشرة تحتاج فركاً أقسى. الروتين المحدود والمتابعة يحميان الحاجز الجلدي ويقللان التجارب العشوائية.","Shine does not mean skin needs harsher scrubbing. A limited routine and follow-up protect the skin barrier and reduce random experiments."), key:L("علاج حب الشباب للبشرة الدهنية","acne treatment for oily skin"), focus:L("البشرة الدهنية وحب الشباب يحتاجان خطة لطيفة ومنظمة، لا تجفيفاً مفرطاً أو خلط منتجات كثيرة","Oily skin and acne need a gentle, organised plan, not excessive drying or many mixed products"), pattern:L("مكان الحبوب وعمقها والحكة أو الألم والمنتجات المستخدمة ومدة المشكلة كلها تفرق بين الاحتمالات","Location, depth, itch or pain, products used and duration all help distinguish possibilities"), factors:L("الحمل أو احتمال الحمل، الأدوية، الدورة، منتجات الشعر والمكياج والعلاجات السابقة يجب ذكرها قبل تغيير الخطة","Pregnancy or possible pregnancy, medicines, cycle, hair or makeup products and earlier treatment should be mentioned before a plan changes"), urgent:L("تورم في الوجه أو العين، طفح منتشر سريع، ألم شديد مع حرارة أو علامات حساسية شديدة يحتاج تقييماً عاجلاً","Facial or eye swelling, a rapidly spreading rash, severe pain with fever or signs of serious allergy need urgent assessment"), source:["American Academy of Dermatology, Acne", "https://www.aad.org/public/diseases/acne"] },
  { slug:"acne-in-teen-girls-assessment", category:"dermatology", specialties:["dermatology"], author:"shimaa-fouad", image:"assets/img/articles/acne-teen-girls-cover.webp", title:L("حب الشباب عند البنات المراهقات: متى نراجع الروتين ومتى نطلب تقييماً؟","Acne in teenage girls: when to review the routine and seek assessment"), excerpt:L("الحبوب شائعة في المراهقة، لكن الألم والندبات والتأثير النفسي والتغيرات الأخرى تستحق نقاشاً منظماً.","Acne is common in adolescence, but pain, scarring, emotional impact and other changes deserve an organised discussion."), key:L("علاج حب الشباب عند البنات","acne treatment for teenage girls"), focus:L("الحبوب عند المراهقات لا تحتاج لوم أو وعوداً سريعة؛ تحتاج تقييماً يحترم البشرة والصحة النفسية والخصوصية","Acne in teenage girls needs neither blame nor quick promises; it needs assessment that respects skin, emotional wellbeing and privacy"), pattern:L("وقت ظهور الحبوب وعمقها وأماكنها وما تم تجربته وأثرها على المدرسة أو الثقة بالنفس معلومات مهمة","Onset, depth and location of spots, what has been tried and effect on school or confidence are important information"), factors:L("الدورة والأدوية ومنتجات البشرة أو الشعر والحمل عند وجود احتمال وأي تغير هرموني آخر يجب مناقشتها بأمان","Cycle, medicines, skin or hair products, pregnancy where possible and other hormonal changes should be discussed safely"), urgent:L("تورم مفاجئ في الوجه، طفح شديد بعد منتج، صعوبة تنفس أو ألم شديد مع حرارة يحتاج رعاية عاجلة","Sudden facial swelling, a severe rash after a product, breathing difficulty or severe pain with fever needs urgent care"), source:["American Academy of Dermatology, Acne", "https://www.aad.org/public/diseases/acne"] },
  { slug:"cellulite-exercise-realistic-expectations", category:"body-contouring", specialties:["body-contouring","clinical-nutrition"], author:"shimaa-fouad", image:"assets/img/articles/cellulite-exercise-cover.webp", title:L("السيلوليت والرياضة: ما الذي قد يتحسن وما الذي لا تعد به التمارين؟","Cellulite and exercise: what may improve and what exercise cannot promise"), excerpt:L("الحركة مفيدة للصحة، لكن السيلوليت مرتبط ببنية الجلد والأنسجة ولا يوجد تمرين يضمن إزالته.","Movement benefits health, but cellulite relates to skin and tissue structure; no exercise can guarantee its removal."), key:L("علاج السيلوليت بالرياضة","cellulite treatment with exercise"), focus:L("الرياضة قد تخدم الصحة والقوة والشعور العام، لكنها ليست وعداً بإزالة السيلوليت أو تغيير الجلد في موعد محدد","Exercise can support health, strength and wellbeing, but is not a promise to remove cellulite or change skin by a fixed date"), pattern:L("مظهر الجلد قد يتغير مع الإضاءة والوضعية والجلوس وتغير الوزن، لذلك المقارنة العادلة أهم من صورة واحدة","Skin appearance can change with lighting, position, sitting and weight shifts, so fair comparison matters more than one photo"), factors:L("الوراثة وبنية الجلد والأنسجة والعمر وتغير الوزن والعادات تؤثر في المظهر بصورة مختلفة بين الأشخاص","Genetics, skin and tissue structure, age, weight change and habits affect appearance differently between people"), urgent:L("ألم جديد واضح، احمرار أو سخونة، تورم في ساق واحدة أو تغير سريع لا يشبه السيلوليت المعتاد يحتاج تقييماً طبياً","New marked pain, redness or warmth, one-leg swelling or a rapid change unlike usual cellulite needs medical assessment"), source:["American Academy of Dermatology, Cellulite", "https://www.aad.org/public/cosmetic/younger-looking/cellulite-treatments"] },
  { slug:"cellulite-home-care-and-safety", category:"body-contouring", specialties:["body-contouring"], author:"shimaa-fouad", image:"assets/img/articles/cellulite-home-care-cover.webp", title:L("السيلوليت في المنزل: عناية واقعية ومتى تحتاج تقييماً؟","Cellulite at home: realistic care and when assessment is needed"), excerpt:L("الكريمات والتدليك قد تغير الإحساس أو المظهر مؤقتاً عند بعض الناس، لكنها لا تبرر منتجات مجهولة أو إجراءات منزلية مؤذية.","Creams and massage may temporarily alter feel or appearance for some people, but do not justify unknown products or harmful home procedures."), key:L("علاج السيلوليت في المنزل","cellulite treatment at home"), focus:L("العناية المنزلية للسيلوليت يجب أن تبدأ بالسلامة وتوقعات واقعية، لا وعود بإذابة دهون أو إزالة دائمة","Home care for cellulite should start with safety and realistic expectations, not promises of fat melting or permanent removal"), pattern:L("الفرق بين السيلوليت الطبيعي وبين ألم أو تورم أو تغير جديد في الجلد مهم قبل تجربة أي منتج","The difference between typical cellulite and pain, swelling or a new skin change matters before trying any product"), factors:L("حساسية الجلد، الإكزيما، الحمل، الرضاعة، الأدوية ومنتجات سابقة تغير ملاءمة أي منتج أو إجراء","Skin sensitivity, eczema, pregnancy, breastfeeding, medicines and prior products change the suitability of any product or procedure"), urgent:L("طفح مؤلم، تقرح، تورم سريع، احمرار مع حرارة أو أعراض حساسية عامة يستدعي تقييماً عاجلاً","A painful rash, ulceration, rapid swelling, red-hot skin or general allergy symptoms require urgent assessment"), source:["American Academy of Dermatology, Cellulite", "https://www.aad.org/public/cosmetic/younger-looking/cellulite-treatments"] },
  { slug:"gallbladder-surgery-operation-day-guide", category:"general-surgery", specialties:["general-surgery"], author:"mohab-ashraf", image:"assets/img/articles/gallbladder-operation-day-cover.webp", title:L("يوم عملية المرارة: كيف تستعد وما الذي تسأل عنه؟","Gallbladder surgery day: how to prepare and what to ask"), excerpt:L("خطة العملية والتخدير والاستعداد تختلف بحسب الحالة. اتبع تعليمات فريق الجراحة بدلاً من نصائح عامة عن الصيام أو الأدوية.","Surgery, anaesthesia and preparation plans differ by case. Follow the surgical team’s instructions rather than general fasting or medicine advice."), key:L("عملية المرارة بالمنظار كم تستغرق","gallbladder surgery what to expect"), focus:L("يوم عملية المرارة يحتاج خطة مكتوبة من فريق الجراحة عن الطعام والشراب والأدوية والوصول والتعافي، لا افتراضات من تجارب الآخرين","Gallbladder surgery day needs a written plan from the surgical team for food, drink, medicines, arrival and recovery, not assumptions from others’ experiences"), pattern:L("سبب العملية، الأعراض، نتائج الفحوص، جراحات سابقة وأي أدوية أو حساسية تؤثر في التفاصيل التي يناقشها الفريق","Reason for surgery, symptoms, test results, earlier operations and medicines or allergies affect the details the team discusses"), factors:L("السكري، أدوية السيولة، الحمل، مشاكل القلب أو التنفس، التدخين والدعم المتاح بعد الخروج أمور يجب ذكرها مبكراً","Diabetes, blood-thinning medicines, pregnancy, heart or breathing concerns, smoking and support after discharge should be raised early"), urgent:L("بعد العملية، صعوبة تنفس، ألم صدر، نزف واضح، إغماء، قيء لا يتوقف أو ألم يتزايد بسرعة يحتاج تقييماً عاجلاً","After surgery, breathing difficulty, chest pain, clear bleeding, fainting, unrelenting vomiting or rapidly worsening pain needs urgent assessment"), source:["NHS, Gallbladder removal", "https://www.nhs.uk/conditions/gallbladder-removal/"] },
  { slug:"abdominal-wall-hernia-symptoms-guide", category:"general-surgery", specialties:["general-surgery"], author:"mohab-ashraf", image:"assets/img/articles/abdominal-hernia-symptoms-cover.webp", title:L("أعراض فتق جدار البطن: البروز والألم ومتى تحتاج مراجعة؟","Abdominal-wall hernia symptoms: bulge, pain and when to seek review"), excerpt:L("ليس كل بروز فتقاً، وليس كل فتق طارئاً. مكان البروز وتغيره والألم والأعراض المصاحبة توجه الأولوية.","Not every bulge is a hernia, and not every hernia is an emergency. Location, change, pain and accompanying symptoms guide urgency."), key:L("أعراض فتق البطن عند النساء والرجال","abdominal wall hernia symptoms"), focus:L("البروز في جدار البطن يحتاج تقييماً لتحديد طبيعته وخطة المتابعة، وليس تشخيصاً من صورة أو من الإحساس فقط","An abdominal-wall bulge needs assessment to identify its nature and follow-up plan, not a diagnosis from a photograph or feeling alone"), pattern:L("مكان البروز، ظهوره مع الوقوف أو الكحة، هل يعود للداخل، وجود ألم أو تغيرات في الإخراج تفاصيل مفيدة للفريق","Location, appearance with standing or coughing, whether it reduces, pain and bowel changes are useful details for the team"), factors:L("الحمل والولادة أو القيصرية، جراحة سابقة، سعال مزمن، إمساك، حمل أشياء ثقيلة وتغير الوزن قد تهم في القصة","Pregnancy and birth or caesarean delivery, earlier surgery, chronic cough, constipation, heavy lifting and weight changes may matter in the history"), urgent:L("ألم مفاجئ شديد في البروز، قيء، انتفاخ بطن، بروز لا يرجع أو تغير لون الجلد يحتاج تقييماً عاجلاً","Sudden severe pain at a bulge, vomiting, abdominal swelling, a non-reducing bulge or skin-colour change needs urgent assessment"), source:["NHS, Hernia", "https://www.nhs.uk/conditions/hernia/"] },
  { slug:"sleeve-gastrectomy-operation-day-recovery", category:"bariatric-surgery", specialties:["bariatric-surgery"], author:"shimaa-fouad", image:"assets/img/articles/sleeve-operation-day-cover.webp", title:L("يوم تكميم المعدة وبداية التعافي: أسئلة التحضير والمتابعة","Sleeve gastrectomy day and early recovery: preparation and follow-up questions"), excerpt:L("التكميم قرار جراحي يحتاج تحضيراً وموافقة مستنيرة وخطة متابعة. تفاصيلك الطبية هي التي تحدد التعليمات.","Sleeve surgery is a surgical decision needing preparation, informed consent and follow-up. Your medical details determine instructions."), key:L("عملية تكميم المعدة بالمنظار","sleeve gastrectomy surgery day"), focus:L("التكميم ليس يوماً واحداً؛ يبدأ بتقييم وتحضير ثم متابعة غذائية وجراحية وطبية طويلة المدى","Sleeve surgery is not one day; it begins with assessment and preparation, then long-term nutrition, surgical and medical follow-up"), pattern:L("الأهداف الصحية، تاريخ الوزن، الأدوية، النوم، الصحة النفسية، جراحات سابقة والدعم في البيت تدخل في التحضير","Health goals, weight history, medicines, sleep, mental wellbeing, earlier surgery and home support all inform preparation"), factors:L("التدخين، أدوية السيولة أو السكر، الحمل أو خططه، نقص العناصر والتاريخ الجراحي يجب مناقشتها مع الفريق","Smoking, blood-thinning or diabetes medicines, pregnancy or plans, nutrient deficiencies and surgical history should be discussed with the team"), urgent:L("بعد الجراحة، ألم صدر، ضيق نفس، حرارة، نبض سريع مستمر، قيء لا يتوقف، ألم شديد متزايد أو عدم القدرة على الشرب يحتاج تقييماً عاجلاً","After surgery, chest pain, breathlessness, fever, persistent fast pulse, relentless vomiting, increasing severe pain or inability to drink need urgent assessment"), source:["ASMBS, Bariatric Surgery FAQs", "https://asmbs.org/patients/bariatric-surgery-faqs/"] },
  { slug:"therapeutic-nutrition-first-visit-guide", category:"clinical-nutrition", specialties:["clinical-nutrition"], author:"shimaa-fouad", image:"assets/img/articles/therapeutic-nutrition-visit-cover.webp", title:L("زيارة التغذية العلاجية الأولى: كيف تستعد لخطة قابلة للاستمرار؟","Your first therapeutic-nutrition visit: preparing for a sustainable plan"), excerpt:L("أفضل خطة ليست الأكثر صرامة، بل التي تربط الهدف الصحي بالأكل والدواء والروتين والقدرة على المتابعة.","The best plan is not the strictest one; it links a health goal with food, medicines, routine and ability to follow up."), key:L("دكتور تغذية علاجية قريب مني","therapeutic nutrition first visit"), focus:L("زيارة التغذية العلاجية تبدأ بفهم الهدف الصحي والحياة اليومية، لا بجدول موحد أو حكم على الإرادة","A therapeutic-nutrition visit starts by understanding health goals and daily life, not a uniform menu or a judgement of willpower"), pattern:L("أوقات الأكل والجوع والشبع، العمل أو الدراسة، النوم، الأدوية، التحاليل السابقة والهدف الذي يهمك هي بيانات مفيدة","Meal times, hunger and fullness, work or study, sleep, medicines, earlier tests and the goal that matters to you are useful information"), factors:L("الحمل والرضاعة، السكري، أمراض الكلى أو الكبد، اضطرابات الأكل، الحساسية، الميزانية والثقافة الغذائية تغير شكل الخطة","Pregnancy and breastfeeding, diabetes, kidney or liver conditions, eating concerns, allergies, budget and food culture change the shape of a plan"), urgent:L("إغماء متكرر، قيء مستمر، جفاف، تدهور سريع في الأكل أو أفكار لإيذاء النفس يحتاج رعاية عاجلة لا موعد تغذية روتيني","Repeated fainting, persistent vomiting, dehydration, rapidly worsening intake or thoughts of self-harm need urgent care, not a routine nutrition visit"), source:["Academy of Nutrition and Dietetics, Nutrition Care", "https://www.eatright.org/health/wellness/your-health/what-is-a-registered-dietitian-nutritionist"] },
  { slug:"body-fat-percentage-context-men-women", category:"body-contouring", specialties:["clinical-nutrition","body-contouring"], author:"shimaa-fouad", image:"assets/img/articles/body-fat-percentage-cover.webp", title:L("نسبة دهون الجسم للرجال والنساء: لماذا لا يكفي رقم واحد؟","Body-fat percentage for men and women: why one number is not enough"), excerpt:L("رقم الدهون يتأثر بطريقة القياس والظروف والسياق الصحي. المقارنة العادلة عبر الوقت أهم من تصنيف سريع.","A body-fat number is affected by the measurement method, conditions and health context. Fair comparison over time matters more than a quick label."), key:L("نسبة الدهون في الجسم للرجال والنساء","body fat percentage for men and women"), focus:L("نسبة دهون الجسم تقدير يمكن أن يفيد المتابعة، لكنها لا تختصر الصحة أو تحدد هدفاً مناسباً لكل شخص","Body-fat percentage is an estimate that can support follow-up, but it does not summarise health or set an appropriate goal for everyone"), pattern:L("طريقة القياس ووقته وتغير السوائل والنشاط والأكل قبل القياس قد تحرك الرقم من دون أن تعني تغيراً صحياً حقيقياً","Measurement method and timing, fluid shifts, activity and food before a scan can move a number without showing a meaningful health change"), factors:L("العمر والهرمونات والحمل عند وجوده والرياضة والأدوية والأمراض والهدف الصحي تغير تفسير النتيجة","Age, hormones, pregnancy where relevant, exercise, medicines, conditions and health goals change how a result is interpreted"), urgent:L("لا تستخدم نسبة الدهون لتفسير إغماء أو ألم صدر أو ضيق نفس أو فقدان وزن غير مقصود أو أعراض حادة؛ هذه تحتاج تقييماً طبياً مستقلاً","Do not use body-fat percentage to explain fainting, chest pain, breathlessness, unintentional weight loss or acute symptoms; these need independent medical assessment"), source:["Cleveland Clinic, Body Composition", "https://my.clevelandclinic.org/health/diagnostics/22523-body-composition"] }
];

const en = (t) => [
  ["Start with the question, not a conclusion", `${t.focus.en}. People may arrive after searching “${t.key.en}”, but a search phrase cannot confirm a diagnosis, identify a safe procedure or choose a treatment. This guide is designed to make a clinical conversation more useful: it explains which observations matter, what a clinician may consider and which changes should move the conversation sooner. It does not replace examination, testing or an individual plan.`],
  ["Describe the pattern over time", `${t.pattern.en}. A short, factual record is often more useful than trying to remember everything at once. Note when the concern began, whether it is constant or episodic, what changes it, what has already been tried and how it affects sleep, work, school, eating or activity. This is not homework to earn care; it gives the clinician a clearer starting point.`],
  ["Context changes the meaning", `${t.factors.en}. The same symptom or measurement can mean something different from one person to another. For that reason, avoid using a friend’s result, an influencer’s routine or a single online checklist as a personal answer. A safe plan begins by putting the concern beside the wider health story.`],
  ["What assessment may include", `Assessment usually starts with listening carefully and deciding whether examination, observation, laboratory tests, imaging, referral or no immediate test is the most useful next step. Tests are not a scorecard and a normal-looking result does not always end the conversation; each result answers a particular clinical question. Ask what question is being asked, how to prepare and when the result will be discussed.`],
  ["Keep day-to-day steps proportionate", `While waiting for assessment, choose low-risk steps that do not hide important information or create a new problem. Keep routines as steady as practical, do not begin prescription medicines or high-dose supplements from online advice, and avoid changing many things at the same time. If food, movement, skin care or symptom tracking is relevant, use it as information for follow-up rather than a test of discipline.`],
  ["Avoid common shortcuts", `A dramatic promise can be especially tempting when a concern is uncomfortable or visible. Be careful with unknown-source products, borrowed medicines, extreme restriction, unverified injections, repeated self-testing or advice that says one sign proves one condition. “Natural”, “fast” and “guaranteed” are marketing words, not a clinical assessment. Bring product names, photographs and labels to the appointment rather than guessing.`],
  ["Decisions should be shared and specific", `A useful plan explains the expected benefit, limits, alternatives, possible harms and how progress will be reviewed. The right option can differ according to pregnancy, age, other conditions, current medicines, previous procedures and personal priorities. It is reasonable to ask what would make the plan change, what should be monitored and who to contact between appointments. Clear questions support informed decisions.`],
  ["Prepare for the appointment", `Bring a short timeline, a list of medicines and supplements, relevant results and questions you do not want to forget. If photographs or a diary would help, ask the clinic what format is useful. Mention anything that feels embarrassing, including over-the-counter products or treatments bought online; those details can materially affect safety. The goal is not to arrive with a diagnosis, but with an accurate story.`],
  ["When not to wait", `${t.urgent.en}. If you are unsure how urgent a change is, seek medical advice rather than trying to sort it out through an article. Urgency depends on the whole situation, including age, pregnancy, health conditions and how quickly symptoms are changing.`],
  ["Make follow-up measurable", `Before leaving a visit, ask what “better” means in this case. It might mean relief of a symptom, a safer routine, a trend over time, a result reviewed in context or simply knowing which warning signs matter. Agree on a review point and on what information to bring back. This prevents a plan from becoming a vague instruction that is difficult to follow or evaluate.`],
  ["A note on online information", `Educational pages are useful for preparing questions, not for delaying care or copying another person’s treatment. Health information changes and individual circumstances matter. Use this page together with the advice of the clinician who can examine you, review your history and explain what applies to your situation.`],
  ["Questions to ask about evidence", `When an option is suggested, ask what evidence supports it for the particular concern, what the likely benefit looks like in real life and what uncertainty remains. A responsible answer may be “we need more information first” or “this may help one part of the problem but not all of it.” That is not a failure to provide care; it is a way of avoiding unnecessary treatment and making expectations honest. Ask whether a reputable guideline or patient-information source is available if you would like to read more between visits.`],
  ["How to judge a claim online", `Check who is making a claim, whether they name the active ingredient or method, whether they explain risks and whether they acknowledge that different people need different care. Testimonials can describe an experience but cannot show that an intervention is safe or suitable for everyone. Before spending money or changing a routine, pause when the message relies on fear, shame, a countdown, a secret formula or a guarantee. Reliable care should leave room for questions and informed consent.`],
  ["Supporting a sustainable routine", `A sustainable routine is usually built from small decisions that fit actual life: sleep, work, family meals, access to care, symptoms and emotional wellbeing. It is not useful to create a plan that can only be followed perfectly for a few days. If a recommendation feels impossible, say so at follow-up. The team can often help identify the barrier, adapt the step or decide that a different priority comes first. Honest feedback improves the plan more than silent struggle.`],
  ["Use results without losing perspective", `Numbers, photographs and symptom scores can be useful when collected consistently, but they should not become the whole story. They may fluctuate for ordinary reasons and they do not measure dignity, effort or every aspect of health. Discuss changes with the clinician who knows why they were collected. If tracking makes anxiety worse or leads to restrictive, compulsive or unsafe behaviour, mention that early. A follow-up tool should support care, not make daily life narrower.`],
  ["Keep the care team informed", `Tell each clinician involved in your care about relevant diagnoses, medicines, supplements and procedures. This is especially important before surgery, during pregnancy, when starting a new medicine or when several specialties are involved. A complete list reduces avoidable misunderstandings. It also helps the team coordinate which question each appointment is answering instead of repeating a test or giving advice that conflicts with another part of the plan.`],
  ["Do not stop prescribed treatment abruptly", `If you think a medicine, supplement or procedure may be linked to a symptom, contact the clinician or pharmacist who can advise safely. Stopping or doubling a prescribed treatment without guidance can create a separate risk. Keep the package, name, dose and timing available for the conversation. If there is a suspected severe allergy, serious side effect or emergency symptom, seek urgent care according to the situation.`],
  ["Choose information that fits the question", `A good question is specific: what are we trying to explain, rule out, monitor or improve? That makes it easier to tell whether a new article, video or social-media post is relevant. Broad health content can be reassuring, but it cannot take account of an examination or a result that is unique to you. Save reliable information for discussion rather than using it to self-prescribe.`],
  ["Plan for review, not perfection", `Health plans often need adjustment. A plan may change because symptoms settle, results add context, a side effect appears or the practical routine is not workable. Review is a normal part of safe care, not evidence that someone has failed. Keep a short list of what improved, what worsened and what was difficult; it gives the next appointment a useful, human starting point.`],
  ["Individual priorities matter", `The best next step is the one that matches the clinical question and your circumstances. Say what matters to you, including pain, uncertainty, time, cost concerns, privacy, family responsibilities or a previous difficult healthcare experience. Those priorities help turn general information into a plan that is both medically sensible and realistically workable.`],
  ["Key message", `${t.focus.en}. A calm, evidence-aware process is usually safer and more useful than a quick answer. Record the relevant pattern, bring the context, ask what the next step is designed to answer and seek urgent care when warning signs appear.`]
];
const ar = (t) => [
  ["ابدأ بالسؤال وليس بالحكم", `${t.focus.ar}. ممكن تبحث عن “${t.key.ar}”، لكن صيغة البحث لا تؤكد تشخيصاً ولا تحدد إجراءً آمناً أو علاجاً مناسباً. الهدف من المقال إنك تجهز لحديث أوضح مع الطبيب: ما التفاصيل المهمة، وما الذي قد يدخل في التقييم، ومتى نسرّع الخطوة. لا يغني ذلك عن الفحص أو التحاليل أو الخطة الفردية.`],
  ["وصف النمط مع الوقت أهم من ذكر عرض واحد", `${t.pattern.ar}. سجل باختصار متى بدأت المشكلة، هل تأتي وتذهب، ما الذي يغيرها، ما الذي جربته وكيف أثرت على النوم أو الشغل أو الدراسة أو الأكل أو الحركة. التسجيل ليس اختباراً لك؛ هو نقطة بداية أوضح للفريق.`],
  ["السياق يغير معنى نفس المعلومة", `${t.factors.ar}. العرض أو القياس نفسه قد يعني شيئاً مختلفاً من شخص لآخر. لذلك لا تجعل نتيجة صديق أو روتين مشهور أو قائمة على الإنترنت إجابة شخصية لك. الخطة الآمنة تبدأ بوضع المشكلة داخل القصة الصحية الكاملة.`],
  ["ماذا قد يشمل التقييم؟", `التقييم غالباً يبدأ بالقصة والفحص وتحديد هل الأنسب متابعة أو تحليل أو تصوير أو إحالة أو عدم الحاجة لفحص فوري. التحاليل ليست درجة نجاح، والنتيجة الطبيعية لا تنهي كل سؤال دائماً؛ كل فحص يجيب عن سؤال محدد. اسأل ما السؤال، وكيف تستعد، ومتى ستراجع النتيجة.`],
  ["اجعل الخطوات اليومية متوازنة", `أثناء انتظار التقييم، اختر خطوات قليلة الخطورة ولا تخفي معلومات مهمة أو تخلق مشكلة جديدة. حاول ثبات الروتين قدر الإمكان، ولا تبدأ دواءً موصوفاً أو مكملات بجرعات عالية من نصيحة الإنترنت، ولا تغير أشياء كثيرة مرة واحدة. لو الأكل أو الحركة أو العناية أو تسجيل الأعراض مناسب، استخدمه كمعلومة للمتابعة لا كاختبار إرادة.`],
  ["احذر الاختصارات الشائعة", `الوعد الكبير قد يكون مغرياً عندما تكون المشكلة مزعجة أو ظاهرة. احذر المنتجات مجهولة المصدر، أدوية الآخرين، الحرمان القاسي، الحقن غير الواضحة، التحاليل المتكررة من غير خطة أو النصيحة التي تقول إن علامة واحدة تثبت مرضاً واحداً. كلمات مثل طبيعي وسريع ومضمون ليست تقييماً طبياً. خذ اسم المنتج أو صورته أو ملصقه للموعد.`],
  ["القرار المفيد واضح ومشترك", `الخطة الجيدة تشرح الفائدة المتوقعة وحدودها والبدائل والمخاطر المحتملة وكيف ستتم المتابعة. الاختيار المناسب يختلف مع العمر والحمل والأدوية والأمراض والإجراءات السابقة والأولويات. من حقك أن تسأل ما الذي قد يغير الخطة، وما الذي نراقبه، ومن تتواصل معه بين الزيارات.`],
  ["حضّر للزيارة", `خذ خطاً زمنياً قصيراً، وقائمة الأدوية والمكملات والنتائج المهمة وأسئلتك. لو الصور أو سجل يومي مفيدين، اسأل العيادة عن الشكل المناسب. اذكر حتى المنتجات أو العلاجات التي تبدو محرجة أو اشتريتها أونلاين؛ قد تؤثر فعلاً في الأمان. الهدف ليس أن تصل بتشخيص، بل بقصة دقيقة.`],
  ["متى لا ننتظر؟", `${t.urgent.ar}. لو لم تكن متأكداً من درجة الاستعجال، اطلب نصيحة طبية بدلاً من محاولة حسمها من مقال. الأولوية تتغير حسب العمر والحمل والأمراض وسرعة تغير الأعراض.`],
  ["اجعل المتابعة قابلة للقياس", `قبل نهاية الزيارة اسأل ماذا يعني تحسن في هذه الحالة: هل هو عرض أخف، روتين أكثر أماناً، اتجاه مع الوقت، نتيجة تقرأ في سياقها أم معرفة علامات الخطر؟ اتفق على موعد مراجعة وما الذي ستأخذه معك. هكذا لا تتحول الخطة إلى تعليمات غامضة صعبة التطبيق أو التقييم.`],
  ["ملاحظة عن المعلومات على الإنترنت", `المقال يساعدك في تحضير الأسئلة، لكنه لا ينبغي أن يؤخر الرعاية أو ينسخ علاج شخص آخر. المعلومات الصحية تتغير والظروف الفردية تفرق. استخدمه مع نصيحة الطبيب الذي يستطيع الفحص ومراجعة تاريخك وشرح ما يناسبك.`],
  ["أسئلة مهمة عن الدليل", `لو اقترح الفريق خياراً، اسأل ما الدليل المناسب لهذه المشكلة، وما شكل الفائدة المتوقعة في الحياة الواقعية، وما الذي ما زال غير مؤكد. الإجابة المسؤولة قد تكون أننا نحتاج معلومات أكثر أولاً، أو أن الخطوة قد تساعد جزءاً من المشكلة وليس كلها. هذا ليس نقصاً في الرعاية؛ هو طريقة لتجنب علاج غير لازم وتوقعات غير واقعية. اسأل عن مصدر موثوق أو إرشاد للمريض لو تحب أن تقرأ بين الزيارات.`],
  ["كيف تقرأ ادعاءً أونلاين؟", `انظر لمن يقدم الادعاء، وهل يذكر المادة أو الطريقة بوضوح، وهل يشرح المخاطر، وهل يعترف بأن الناس احتياجاتهم مختلفة. تجربة شخص قد تشرح ما مر به، لكنها لا تثبت أن الإجراء آمن أو مناسب للجميع. قبل دفع مال أو تغيير روتين، توقف عند رسالة تعتمد على الخوف أو الإحراج أو عرض محدود أو تركيبة سرية أو نتيجة مضمونة. الرعاية الموثوقة تترك مساحة للأسئلة والموافقة الواعية.`],
  ["روتين يمكن استمراره", `الروتين القابل للاستمرار غالباً يبنى من خطوات صغيرة تناسب الحياة الحقيقية: النوم والشغل ووجبات الأسرة والوصول للرعاية والأعراض والحالة النفسية. ليس مفيداً أن نصنع خطة لا يمكن تنفيذها إلا بصورة مثالية لأيام قليلة. لو التوصية تبدو مستحيلة، قل ذلك في المتابعة. يمكن للفريق تحديد العائق أو تعديل الخطوة أو تقديم أولوية أخرى. الملاحظة الصادقة تحسن الخطة أكثر من المعاناة في صمت.`],
  ["استخدم النتائج من غير أن تفقد المنظور", `الأرقام والصور وسجل الأعراض قد تفيد لو جُمعت بظروف متقاربة، لكنها ليست القصة كلها. قد تتذبذب لأسباب عادية ولا تقيس الكرامة أو الجهد أو كل جوانب الصحة. ناقش التغير مع الطبيب الذي يعرف لماذا تم جمعها. لو المتابعة نفسها تزيد القلق أو تدفع لسلوك مقيد أو قهري أو غير آمن، اذكر ذلك مبكراً. أداة المتابعة ينبغي أن تخدم الرعاية لا أن تضيق الحياة.`],
  ["خلّي فريقك يعرف الصورة", `اذكر لكل طبيب أو مختص مهم في رعايتك الأمراض والأدوية والمكملات والإجراءات ذات الصلة. هذا مهم خصوصاً قبل الجراحة وأثناء الحمل وعند بدء دواء جديد أو وجود أكثر من تخصص. القائمة الكاملة تقلل سوء الفهم الذي يمكن تجنبه. كما تساعد الفريق في تنسيق السؤال الذي تجيب عنه كل زيارة بدلاً من تكرار فحص أو إعطاء نصيحة تتعارض مع جزء آخر من الخطة.`],
  ["لا توقف العلاج الموصوف فجأة", `لو شككت أن دواءً أو مكملاً أو إجراءً مرتبط بعرض، تواصل مع الطبيب أو الصيدلي الذي يستطيع إرشادك بأمان. إيقاف أو مضاعفة علاج موصوف من غير توجيه قد يخلق خطراً آخر. احتفظ باسم المنتج والجرعة والتوقيت للحديث. لو كان هناك اشتباه حساسية شديدة أو أثر جانبي خطير أو عرض طارئ، اطلب رعاية عاجلة حسب الحالة.`],
  ["اختر معلومة تناسب السؤال", `السؤال الجيد محدد: ما الذي نحاول تفسيره أو استبعاده أو متابعته أو تحسينه؟ هذا يسهل معرفة هل مقال أو فيديو أو منشور مفيد فعلاً. المحتوى العام قد يطمئن، لكنه لا يستطيع أن يحسب الفحص أو النتيجة الخاصة بك. احتفظ بالمصدر الموثوق لمناقشته بدلاً من استخدامه لوصف علاج لنفسك.`],
  ["خطط للمراجعة لا للكمال", `الخطط الصحية غالباً تحتاج تعديلاً. قد تتغير لأن الأعراض هدأت أو النتيجة أضافت سياقاً أو ظهر أثر جانبي أو لم يكن الروتين عملياً. المراجعة جزء طبيعي من الرعاية الآمنة وليست دليلاً أن شخصاً فشل. سجل باختصار ما تحسن وما ساء وما كان صعباً؛ سيعطي الموعد التالي بداية إنسانية ومفيدة.`],
  ["الأولوية الشخصية لها مكان", `أفضل خطوة تالية هي التي تناسب السؤال الطبي وظروفك. قل ما يهمك، بما فيه الألم أو القلق أو الوقت أو خصوصية الموضوع أو مسؤوليات الأسرة أو تجربة صحية سابقة صعبة. هذه الأولويات تساعد في تحويل المعلومة العامة إلى خطة سليمة طبياً ويمكن تنفيذها في الواقع.`],
  ["الخلاصة", `${t.focus.ar}. العملية الهادئة المبنية على دليل عادة أكثر أماناً وفائدة من إجابة سريعة. سجل النمط، خذ السياق للموعد، اسأل ما الذي سيجيب عنه كل خطوة، واطلب الرعاية العاجلة عند ظهور علامات الخطر.`]
];
const FAQ = (t) => [
  { q:L("هل أبدأ علاجاً من الإنترنت؟","Should I start a treatment from the internet?"), a:L("لا. المحتوى العام لا يعرف تاريخك الصحي أو أدويتك أو نتيجة الفحص. استخدمه لتجهيز أسئلتك، وراجع الطبيب أو المختص قبل بدء أو إيقاف علاج أو مكمل أو إجراء.","No. General content does not know your health history, medicines or examination findings. Use it to prepare questions and review any medicine, supplement or procedure with a clinician before starting or stopping it.") },
  { q:L("ما المعلومات التي تساعد في الموعد؟","What information helps at an appointment?"), a:L("وقت البداية، ما الذي تغير، الأدوية والمكملات، المنتجات أو الإجراءات التي جربتها والنتائج السابقة كلها مفيدة. خذ صورة أو سجلاً فقط إذا كان مناسباً للمشكلة أو طلبه الفريق.","Onset, what changed, medicines and supplements, products or procedures tried and previous results are useful. Bring a photograph or diary only when it suits the concern or the team has requested it.") },
  { q:L("هل النتيجة الطبيعية تعني أنه لا توجد مشكلة؟","Does a normal result mean there is no problem?"), a:L("ليس بالضرورة. كل تحليل أو تصوير يجيب عن سؤال محدد، والطبيب يقرأه مع القصة والفحص. اسأل ما الذي توضحه النتيجة وما الخطوة التالية لو استمرت الأعراض.","Not necessarily. Every test or scan answers a particular question and is read with history and examination. Ask what the result explains and what the next step is if symptoms continue.") },
  { q:L("متى أطلب رعاية عاجلة؟","When should I seek urgent care?"), a:L(`${t.urgent.ar} لا تنتظر موعداً عادياً إذا كانت الحالة شديدة أو تتفاقم بسرعة.`,`${t.urgent.en} Do not wait for a routine appointment if the problem is severe or rapidly worsening.`) }
];
const article = (t) => ({ slug:t.slug, type:"article", published:true, featured:false, category:t.category, specialties:t.specialties, date:"2026-09-12", readingTime:12, author:t.author, reviewedBy:t.author, image:t.image, title:t.title, excerpt:t.excerpt, sections:en(t).map(([heading,body], i)=>({id:`section-${i+1}`,heading:L(ar(t)[i][0],heading),body:L(ar(t)[i][1],body)})), faq:FAQ(t), sources:[{label:t.source[0],url:t.source[1]}], tags:L([t.key.ar,"تقييم طبي منظم","معلومات صحية موثوقة"],[t.key.en,"organised assessment","health education"]), seo:{title:L(t.title.ar.slice(0,35),t.title.en.slice(0,35)),description:t.excerpt} });
const out={_note:"Third September 2026 bilingual long-form Knowledge Centre expansion. General education only; individual assessment and the site-wide medical notice apply.",articles:topics.map(article)};
fs.writeFileSync(path.join(ROOT,"content","articles-longform-2026-09-12.json"),JSON.stringify(out,null,2)+"\n","utf8");
console.log(`Wrote ${out.articles.length} long-form bilingual articles.`);
